import{C as d,o as s,c as r,a5 as e,E as a}from"./chunks/framework.URF5zJ_R.js";const y=JSON.parse('{"title":"67 道高频现场面试真题与深层考点 (Interview Prep)","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"11_Interview_Prep.md","filePath":"11_Interview_Prep.md","lastUpdated":1789008202000}'),o={name:"11_Interview_Prep.md"},x=Object.assign(o,{setup(g){const n=[{index:"01",title:"#1 45 分钟白板架构全流程掌控 (The 45-Min Framework)",category:"面试流程 · Core",desc:"白板面试的黄金铁律：需求澄清(5m) -> 容量粗算(5m) -> 高层架构(15m) -> 深度攻坚(15m) -> 容灾监控总结(5m)。时间耗尽是挂掉候选人的第一死因。",meta:{考察重点:"结构化思维、大局观与时间节奏把控",致命扣分:"开场一言不发直接画架构图或深陷局部细节"}},{index:"02",title:"#15 数据分片与分库分表键选择 (Sharding & Partition Key)",category:"数据存储 · Advanced",desc:"系统设计中最具决定性意义的核心决策。需权衡范围分片与哈希分片的优劣，以及如何避免跨分片关联查询与二次聚合开销。",meta:{考察重点:"水平横向伸缩与数据均匀分布能力",深度追问:"分片键为用户ID时如何应对头部 1% 大V热点倾斜"}},{index:"03",title:"#20 超卖与双并发扣减冲突 (Two Users Buy Last Item)",category:"并发事务 · Core",desc:"高并发库存扣减标准考题。深入对比数据库行级悲观锁 SELECT FOR UPDATE、乐观锁版本号控制与 Redis Lua 脚本原子预扣减方案。",meta:{考察重点:"并发事务隔离级别、行级锁开销与竞态解决",实战避坑:"切忌在应用内存完成判断后再裸写更新数据库"}},{index:"04",title:"#23 缓存击穿与热点 Key 过期 (Cache Stampede & Hot Keys)",category:"缓存架构 · Advanced",desc:"高并发下热点数据失效瞬间打垮数据库的工业防范方案：分布式互斥锁重建、后台概率性提前续期 (XFetch) 以及基础 TTL 叠加随机时间抖动。",meta:{考察重点:"缓存雪崩与击穿防范的多层级防御架构",实战避坑:"禁止对海量 Key 设置完全相同的过期时间"}},{index:"05",title:"#30 消息“恰好一次”消费神话 (Exactly-Once Processing)",category:"消息机制 · Advanced",desc:"诚实务实的工程技术直觉：分布式网络物理限制决定了没有绝对单向的恰好一次；真实工业界方案是“至少一次投递 (At-least-once) + 消费端业务幂等校验”。",meta:{考察重点:"分布式物理边界认知与幂等去重表设计",实战避坑:"轻信并向面试官吹嘘“中间件原生保证绝对恰好一次”"}},{index:"06",title:"#35 慢依赖隔离与防级联雪崩 (Bulkhead & Circuit Breaker)",category:"高可用韧性 · Advanced",desc:"微服务集群防雪崩核心军规：舱壁隔离机制 (Bulkhead)、独立线程池/连接池配额隔离、严格超时控制与熔断器 (Circuit Breaker) 快速失败兜底。",meta:{考察重点:"故障域隔离、降级兜底与防雪崩蔓延扩散",实战避坑:"所有下游 RPC 调用共用默认无上限的全局公共线程池"}}];return(i,t)=>{const l=d("CardGrid");return s(),r("div",null,[t[0]||(t[0]=e("",11)),a(l,{items:n,columns:3}),t[1]||(t[1]=e("",4))])}}});export{y as __pageData,x as default};
